pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz the _baseToken and other parameters. The distinguishing property is that
    // reference sets baseToken == _baseToken for all inputs; mutant sets baseToken = address(0).
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Keep inputs in wide admissible ranges. Avoid zero address for nft to keep realistic scenarios,
        // but do not constrain _baseToken (the fuzzer should find a case where _baseToken != address(0)).
        vm.assume(_nft != address(0));
        // feeRate must be <= max allowed; otherwise initialize will revert in both versions and not distinguish.
        _feeRate = uint16(_feeRate % 5001);

        bool ok;
        // call initialize and catch reverts: we only care about successful initialization outcomes
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // Exactly one assertion: in the correct contract baseToken equals the provided _baseToken for ALL inputs;
            // the mutant that forces baseToken = address(0) will cause this assertion to fail for any _baseToken != address(0).
            assertTrue(c.baseToken() == _baseToken);
        } else {
            // If initialization reverted, nothing to assert about post-state; still satisfy requirement of exactly one
            // assert in the successful path. To keep single-assert rule, we simply return when init failed.
            return;
        }
    }
}

