pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz _baseToken and an arbitrary caller address to detect if initialize uses msg.sender instead of the parameter
    function testFuzz_property(address _baseToken, address caller) public {
        // keep wide domain but avoid zero address for caller to ensure distinctness when needed
        // allow _baseToken to be zero (represents native ETH) as admissible per contract
        vm.assume(caller != address(0));

        // perform initialize as if called by `caller`
        vm.startPrank(caller);
        bool ok;
        try c.initialize(_baseToken, address(0x1234), 1, 1, 0, 0, bytes32(0), false, false) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The universal property: after initialize returns successfully (ok == true), baseToken equals the _baseToken argument.
        // The mutant assigns baseToken = msg.sender, so when caller != _baseToken and initialize succeeds, the mutant will fail this assertion.
        if (ok) {
            assertTrue(c.baseToken() == _baseToken);
        } else {
            // if initialization reverted, nothing to assert about state; still satisfy single assertion requirement by asserting ok == ok
            // but per constraints we must have exactly one assertTrue reading c's public surface when possible; here ok==false means initialize reverted,
            // so we assert that initialize indeed reverted by checking ok == false is allowed via a trivial assertTrue on a read (we still need exactly one assertion overall).
            // To keep to a single assertion, we assert that ok implies baseToken==_baseToken; when ok is false, the implication is vacuously true, so assertTrue below covers both.
            assertTrue(!ok || c.baseToken() == _baseToken);
        }
    }
}

