pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz parameters: _feeRate and a boolean that controls whether the reentrant helper will reenter
    function testFuzz_property(uint16 _feeRate, bool doReenter) public {
        // keep feeRate in admissible domain
        vm.assume(_feeRate <= 5000);

        // Deploy a reentrant helper that will, during an external call from initialize (we force such a call by
        // setting nft or baseToken to the helper address and making ERC721/ERC20 calls to it), reenter initialize
        // if doReenter==true. We'll use the helper as the nft address so that safeTransferFrom called during
        // initialize-related flows (if any) will hit the helper.
        ReenterHelper helper = new ReenterHelper(address(c));

        address _baseToken = address(0);
        address _nft = doReenter ? address(helper) : address(1); // if doReenter false, use an EOA-like address

        // Choose other parameters arbitrarily
        uint128 _virtualBaseTokenReserves = 1;
        uint128 _virtualNftReserves = 1;
        uint56 _changeFee = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        // If we want reentrancy, configure helper to attempt reenter during initialize
        helper.setWillReenter(doReenter);

        // Call initialize from this contract (an EOA for the contract under test). Some mutants will be
        // distinguishable when the helper reenters during initialize; the correct contract must always end with
        // feeRate == _feeRate after initialize completes.
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: whenever initialize returned (ok==true), the contract's feeRate getter equals the provided _feeRate.
        // This will hold for the reference implementation for all inputs; the mutant that moved the assignment can be broken by reentrancy
        // and thus produce a case where ok==true but feeRate()!=_feeRate.
        if (ok) {
            assertTrue(c.feeRate() == _feeRate);
        } else {
            // If initialize reverted, nothing to assert about feeRate; still keep test valid for all inputs.
            assertTrue(true);
        }
    }
}

// Helper that can reenter initialize by calling c.initialize again from its fallback
contract ReenterHelper {
    address public target;
    bool public willReenter;

    constructor(address _target) {
        target = _target;
    }

    function setWillReenter(bool v) external {
        willReenter = v;
    }

    // Provide a function that will be called by C if C interacts with this address as an ERC721 token recipient
    // We'll use the fallback to trigger reentrancy into initialize.
    fallback() external payable {
        if (willReenter) {
            // attempt to reenter initialize with a different feeRate to cause ordering differences to be observable
            // Use low-level call to avoid revert bubbling
            C(target).initialize(address(0), address(2), 1, 1, 0, 1234, bytes32(0), false, false);
        }
    }

    receive() external payable {
        if (willReenter) {
            C(target).initialize(address(0), address(2), 1, 1, 0, 1234, bytes32(0), false, false);
        }
    }
}
